const response = await fetch(input.url);
if (!response.ok) throw new Error(`HTTP error ${response.status}`);
globalThis.rawBody = await response.text();
globalThis._contentType = response.headers.get('content-type') || '';

let parsed;
if (globalThis._contentType.includes('application/json')) {
  try {
    parsed = JSON.parse(globalThis.rawBody);
  } catch (e) {
    throw new Error('Failed to parse JSON response');
  }
} else {
  parsed = globalThis.rawBody;
}
globalThis.parsed = parsed;
